**App Name:** DarkCalc
A sleek, fully functional calculator with a dark theme and real-time calculation.

**Initial State:**
```json
{"display":"0","history":"","version":0}
```

```runsplash
height: Fill
flow: Down
spacing: 12
padding: Inset{left: 16 right: 16 top: 16 bottom: 16}

fn append_to_display(val: string) {
    let current = mod.state.app.display
    if current == "0" && val != "." {
        mod.state.app.display = val
    } else {
        mod.state.app.display = current + val
    }
    mod.state.app.version = mod.state.app.version + 1
}

