fn clear_all() {
    mod.state.app.display = "0"
    mod.state.app.history = ""
    mod.state.app.version = mod.state.app.version + 1
}

fn clear_entry() {
    mod.state.app.display = "0"
    mod.state.app.version = mod.state.app.version + 1
}

fn backspace() {
    let current = mod.state.app.display
    if current.len() > 1 {
        mod.state.app.display = current.substr(0, current.len() - 1)
    } else {
        mod.state.app.display = "0"
    }
    mod.state.app.version = mod.state.app.version + 1
}

// Calculator button widget
fn calc_button(text: string, color: string, action: string) {
    View{
        width: Fill height: Fit
        Button{
            text: "" + text
            width: Fill height: 48.0
            padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
            draw_bg +: { color: #x color radius: 8.0 }
            draw_text +: { color: #xffffff text_style: theme.font_bold {font_size: 18} }
            on_click: || {
                if action == "num" { append_to_display(text) }
                else if action == "op" { append_to_display(text) }
                else if action == "eq" { calculate() }
                else if action == "clear" { clear_all() }
                else if action == "ce" { clear_entry() }
                else if action == "bs" { backspace() }
            }
        }
    }
}

// Display area
View{
    width: Fill height: Fit flow: Down spacing: 4
    padding: Inset{left: 20 right: 20 top: 20 bottom: 20}
    show_bg: true new_batch: true
    draw_bg +: { color: #x1e293b radius: 14.0 }

    Label{
        text: "" + mod.state.app.history
        draw_text +: { text_style: theme.font_regular {font_size: 12} color: #x64748b align: Right }
    }
    Label{
        text: "" + mod.state.app.display
        draw_text +: { text_style: theme.font_bold {font_size: 42} color: #xf1f5f9 align: Right }
    }
}

// Button grid
View{
    width: Fill height: Fit flow: Down spacing: 8

    // Row 1: Clear, Backspace, Percent, Divide
    View{
        width: Fill height: Fit flow: Right spacing: 8
        calc_button("C", "x3b82f6", "clear")
        calc_button("⌫", "x3b82f6", "bs")
        calc_button("%", "x3b82f6", "op")
        calc_button("/", "x3b82f6", "op")
    }

    // Row 2: 7, 8, 9, Multiply
    View{
        width: Fill height: Fit flow: Right spacing: 8
        calc_button("7", "x1e293b", "num")
        calc_button("8", "x1e293b", "num")
        calc_button("9", "x1e293b", "num")
        calc_button("x", "x3b82f6", "op")
    }

    // Row 3: 4, 5, 6, Subtract
    View{
        width: Fill height: Fit flow: Right spacing: 8
        calc_button("4", "x1e293b", "num")
        calc_button("5", "x1e293b", "num")
        calc_button("6", "x1e293b", "num")
        calc_button("-", "x3b82f6", "op")
    }

    // Row 4: 1, 2, 3, Add
    View{
        width: Fill height: Fit flow: Right spacing: 8
        calc_button("1", "x1e293b", "num")
        calc_button("2", "x1e293b", "num")
        calc_button("3", "x1e293b", "num")
        calc_button("+", "x3b82f6", "op")
    }

    // Row 5: 0, ., =
    View{
        width: Fill height: Fit flow: Right spacing: 8
        View{ width: Fill height: Fit } // Spacer
        calc_button("0", "x1e293b", "num")
        calc_button(".", "x1e293b", "num")
        calc_button("=", "x22c55e", "eq")
    }
}
